insert into public.content (id, kind, published, data) values ('home', 'pages', true, '{"id":"home","kind":"pages","title":"Votre événement.\nVotre vision.\nNotre savoir-faire.","description":"Des premières idées aux derniers instants, nous imaginons des événements qui vous ressemblent.","published":true,"subtitle":"CRÉATEUR D’ÉMOTIONS · MAROC","image":"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=2000&q=85","demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('about', 'pages', true, '{"id":"about","kind":"pages","title":"L’art de donner vie\nà vos envies.","description":"Eventheme réunit organisation, animation, décoration et location de matériel pour créer des moments singuliers. Une célébration intime ou un rendez-vous professionnel : chaque projet commence par votre vision.","published":true,"subtitle":"L’ESPRIT EVENTHEME","image":"https://images.unsplash.com/photo-1465495976277-4387d4b0b4c6?auto=format&fit=crop&w=1400&q=85","demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('values', 'pages', true, '{"id":"values","kind":"pages","title":"Le sens du détail.\nL’essentiel de l’émotion.","description":"Écouter avec attention. Imaginer avec audace. Préparer avec précision. Notre approche associe créativité et coordination pour vous accompagner à chaque étape.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('contact', 'pages', true, '{"id":"contact","kind":"pages","title":"Tout commence\npar une conversation.","description":"Une idée, une date, une envie ? Racontez-nous votre projet. Nous construirons ensemble un événement à votre image.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('events-page', 'pages', true, '{"id":"events-page","kind":"pages","title":"À chaque occasion,\nune émotion.","description":"Des moments privés aux grands rendez-vous professionnels, imaginons une expérience qui vous ressemble.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('services-page', 'pages', true, '{"id":"services-page","kind":"pages","title":"Votre vision,\nnotre savoir-faire.","description":"Un accompagnement complet ou une expertise à la carte. Choisissez ce qui donnera vie à votre événement.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
